try:
    print('>>> f = getattr')
    print('>>> x = ""')
    print('>>> y = {}')
    print('>>> f(x, y)')
    f = getattr
    x = ""
    y = {}
    print(f(x, y))
except Exception as e:
    print(type(e), ':', e)
print()
